<template><view class="page"><view class="glow"></view><view class="brand">遇见 <text>MEET</text></view><view class="hero"><text class="eyebrow">MAKE EVERY CONNECTION COUNT</text><text class="title">让相遇，刚刚好。</text><text class="sub">发现有趣的人，分享生活里的每个瞬间</text></view><view class="panel"><view class="switch"><text :class="{on:mode==='login'}" @tap="mode='login'">登录</text><text :class="{on:mode==='register'}" @tap="mode='register'">注册</text></view><input v-model="phone" placeholder="手机号" type="number"/><input v-model="code" placeholder="验证码 / 密码" password/><view v-if="mode==='register'" class="hint">注册即表示同意《用户协议》和《隐私政策》</view><text class="forgot" @tap="mode='reset'">忘记密码？</text><button class="primary" @tap="submit">{{mode==='register'?'创建账号':mode==='reset'?'发送重置验证码':'登录 / 继续'}}</button><text class="notice">{{notice}}</text></view><text class="bottom">继续即代表你已年满18周岁</text></view></template><script setup>import {ref} from 'vue';const mode=ref('login'),phone=ref(''),code=ref(''),notice=ref('演示模式：账号验证尚未连接服务端');function submit(){if(!/^[0-9]{10,11}$/.test(phone.value)){notice.value='请输入有效手机号';return}if(!code.value.trim()){notice.value=mode.value==='reset'?'请先填写手机号':'请输入验证码或密码';return}if(mode.value==='reset'){notice.value='重置申请已通过演示校验，正式短信服务需接入后端';return}uni.setStorageSync('meet-session',{phone:phone.value,mode:mode.value});notice.value=mode.value==='register'?'注册资料已校验，演示账号已创建':'登录校验通过，已进入演示账号';setTimeout(()=>uni.reLaunch({url:'/pages/index/index'}),500)}</script><style scoped lang="scss">.page{min-height:100vh;padding:54px 26px 30px;box-sizing:border-box;color:#302b40;background:linear-gradient(150deg,#e0edff,#f8e5f3 55%,#e4f5ff);position:relative;overflow:hidden}.glow{position:absolute;width:280px;height:280px;border-radius:50%;background:#fff;filter:blur(80px);opacity:.7;right:-100px;top:80px}.brand{font-size:25px;font-weight:900;position:relative}.brand text{font-size:10px;letter-spacing:4px;color:#a69ac4;margin-left:8px}.hero{margin:78px 0 34px;position:relative}.eyebrow{font-size:9px;letter-spacing:2px;color:#a18cb8;display:block}.title{font-size:32px;font-weight:900;display:block;margin:14px 0}.sub{font-size:13px;color:#91899c}.panel{position:relative;background:#ffffffb8;border:1px solid #fff;border-radius:26px;padding:24px 20px;box-shadow:0 16px 50px #a89bbd30;backdrop-filter:blur(18px)}.switch{display:flex;gap:28px;margin-bottom:22px;font-weight:700;color:#aaa2b3}.switch .on{color:#d66cae;font-size:20px}input{height:48px;border-radius:14px;background:#f7f4fa;margin:12px 0;padding:0 15px;font-size:14px}.hint,.notice{font-size:11px;color:#a59baa;line-height:1.7}.forgot{display:block;text-align:right;color:#b07bb4;font-size:12px;margin:14px 0}.primary{background:linear-gradient(100deg,#f39bc4,#a99af0);color:white;border:0;border-radius:28px;font-size:15px;margin-top:14px}.bottom{display:block;text-align:center;color:#a59baa;font-size:11px;margin-top:30px}</style>